  // Explicit device-local choice. Existing previews/installations start long.
  const hcPreferenceKey='beecount.homeSummaryLayout';
  let hcCompact=false;try{hcCompact=localStorage.getItem(hcPreferenceKey)==='compact';}catch{}
  const hcOverride=qParams.get('homeSummary');
  if(['standard','compact'].includes(hcOverride))hcCompact=hcOverride==='compact';
  function hcRing(value,label,ratio,over=false){return `<button class="hc-budget-ring" data-action="page:budget" aria-label="${value==='+'?'设置预算':'预算管理'}"><svg viewBox="0 0 86 86" aria-hidden="true"><circle cx="43" cy="43" r="37" class="hc-ring-track"/><circle cx="43" cy="43" r="37" class="hc-ring-progress" style="--hc-remaining:${ratio};${over?'stroke:var(--bc-red)':''}"/></svg><span><strong ${over?'style="color:var(--bc-red)"':''}>${value}</strong><small>${label}</small></span></button>`;}
  const hcPreviousHome=home;
  home=function(){const html=hcPreviousHome();if(!hcCompact)return html;const t=document.createElement('template');t.innerHTML=html;const card=t.content.querySelector('.bc-summary');if(!card)return html;const context=card.querySelector('.bc-between'),month=context.querySelector('.bc-month-button').outerHTML,currency=context.querySelector('.bc-small')?.textContent.trim().split(' ').at(-1)||'CNY',eye=card.querySelector('.bc-eye')?.outerHTML||'',label=card.querySelector('.bc-summary-label')?.childNodes[0]?.textContent||'本月支出',hero=card.querySelector('.bc-hero-value').outerHTML,metrics=card.querySelector('.bc-dual').outerHTML,budget=card.querySelector('.bc-budget'),remaining=budget?.querySelector('.bc-between button')?.textContent||'',over=/[-−]/.test(remaining),spent=parseFloat(budget?.querySelector('.bc-budget-track>span')?.style.width||'0'),ratio=budget?Math.max(0,Math.min(1,1-spent/100)):0,value=!budget?'+':state.hide?'••':over?'超支':Math.round(ratio*100)+'%',caption=!budget?'去设置':over?'预算':'预算可用';
    card.classList.add('hc-summary');card.innerHTML=`<div class="hc-context">${month}<div class="hc-currency">${esc(currency)}${eye}</div></div><div class="hc-primary"><div class="hc-money"><div class="hc-caption">${esc(label)}</div>${hero}</div>${hcRing(value,caption,over?1:ratio,over)}</div>${metrics}`;return t.innerHTML;};
  const hcPreviousSheet=sheet;sheet=function(title,contents){if(state.page==='home'&&title==='常用工具')contents+=menuRow('hc-layout','panels-top-left',hcCompact?'切换为完整汇总':'切换为紧凑汇总','');return hcPreviousSheet(title,contents);};
  root.addEventListener('click',event=>{if(!event.target.closest('[data-action="hc-layout"]'))return;event.preventDefault();event.stopImmediatePropagation();const mainTop=phone.querySelector('.bc-main')?.scrollTop||0,listTop=phone.querySelector('.h-journal-list')?.scrollTop||0;hcCompact=!hcCompact;try{localStorage.setItem(hcPreferenceKey,hcCompact?'compact':'standard');}catch{}rDismiss();render();requestAnimationFrame(()=>{const main=phone.querySelector('.bc-main'),list=phone.querySelector('.h-journal-list');if(main)main.scrollTop=mainTop;if(list)list.scrollTop=listTop;});},true);
  function hcFitMoney(){for(const node of phone.querySelectorAll('.hc-summary .bc-hero-value,.hc-summary .bc-dual strong')){node.style.fontSize='';for(let i=0;i<4&&node.scrollWidth>node.clientWidth+1;i++){const size=parseFloat(getComputedStyle(node).fontSize);node.style.fontSize=(size*node.clientWidth/node.scrollWidth)+'px';}}}
  const hcPreviousAfterRender=qAfterRender;qAfterRender=function(){hcPreviousAfterRender();phone.dataset.homeSummary=hcCompact?'compact':'standard';requestAnimationFrame(hcFitMoney);};
